/**
 * @description Small pieces of an outbound HTTP request that need no records: the resolved path, the headers and
 * null-safe text. Used by IntegrationHubCallout.
 * @group Integration Hub
 */
public with sharing class IntegrationHubRequestParts {

    /**
     * @description The event path with {recordId} and {transactionId} replaced; blank values become empty text.
     * @param path the event path (may be blank)
     * @param recordId the related record Id
     * @param transactionId the transaction Id
     * @return the path to add after the Named Credential URL
     */
    public static String resolvePath(String path, String recordId, String transactionId) {
        return orEmpty(path).replace('{recordId}', orEmpty(recordId)).replace('{transactionId}', orEmpty(transactionId));
    }

    /**
     * @description Sets Content-Type, X-Correlation-Id (when known) and the connection headers on the request.
     * @param req the request
     * @param correlationId the correlation Id (may be blank)
     * @param headersJson the connection headers as a JSON object (may be blank)
     */
    public static void addHeaders(HttpRequest req, String correlationId, String headersJson) {
        req.setHeader('Content-Type', 'application/json');
        if (String.isNotBlank(correlationId)) {
            req.setHeader('X-Correlation-Id', correlationId);
        }
        if (String.isBlank(headersJson)) {
            return;
        }
        Map<String, Object> headers = (Map<String, Object>) JSON.deserializeUntyped(headersJson);
        for (String name : headers.keySet()) {
            Object value = headers.get(name);
            req.setHeader(name, value == null ? '' : String.valueOf(value));
        }
    }

    /**
     * @description Text that is never null.
     * @param value the text
     * @return the text, or empty text for null
     */
    public static String orEmpty(String value) {
        return value == null ? '' : value;
    }
}
